custom_css:
/* ============================================================
    止叹迹@Mayonnaise
   非常感谢导航楼内各位老师的分享，所使用代码已在以下标注作者❤︎============================================================ */
@import url("https://fontsapi.zeoseven.com/285/main/result.css");

body {
    font-family: "Noto Serif CJK";
    font-weight: normal;
}

/* 自定义变量 */
:root {
/* 头像和文本块共同的宽度 */
   --宽度: 350px;

/* == 头像 == */
  --上边距: 40px;
  --高度: 235px;
  --头像左边距: 5.8%;
  --头像混合: normal; /* 头像的特殊效果，不需要这个改成normal即可，其他推荐：color-burn/screen/multiply/overlay */
  --底部渐变: 30%;
  --头像位置: 30% 30%;/* 具体写法去问ai关于object-position */

/* == 文本块 == */
  --文本: "Love is my religion – I could die for that. I could die for you. My Creed i s Love and you are its only tenet.";/* 换行使用\A */
  --文本块高度: 26px;/* 文本显示不全就加大这个 */
  --文本块垂直位置: -23px;

/* == 名字后文本 == */
  --名字后文本: "Toda mi ambición es ser libre toda mi vida";
  --与名字间距: 41px;

/* == 字素 == */
    --字素颜色: #FF0000;
    /* 亮度数值小于1变暗，大于1变亮 */
    --字素亮度: 1.1;
    --字素对比度: 1.1;
    --字素宽度: 410px;
    --字素高度: 55px;
    --字素垂直位置: 190px;
    --字素: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E4%B8%89%E7%89%88/%E6%9C%AA%E6%A0%87%E9%A2%98-1.png');
    --字素层级: 1;/* 被没有特殊效果的头像挡住就改成1 */

/* == 图标 == */
    --编辑按钮: '—';
    --三点按钮: '—';
    --左翻页: '<';
    --右翻页: '>';
    --图标1: '✦';
    --图标2: '⋆';
    --图标3: '✧';
    --图标4: '✶';

/* == 其他 == */
    --思维链: "Amor vincit omnia /";
}

* {
    border-radius: 0!important;
    filter: none!important;
}

/* ============================================================
   2. 聊天区域与消息主体
   ============================================================ */
#chat {
    background: transparent;
    padding-left: 7px;
    padding-right: 7px;
  border: 0;
}

.mes_block{
  padding: 0;
}

.mes {
  margin-top: 10px;
    margin-bottom: 50px;
    background: var(--SmartThemeChatTintColor);
    padding-top: calc(var(--上边距) + var(--高度) + var(--文本块高度));
    padding-bottom: 60px;
    background-image: url("https://www.transparenttextures.com/patterns/concrete-wall.png");
    box-shadow: 0 2px 3px #00000045;
}

.mes::before {
    content: '';
    background-image: var(--字素);
    background-size: 100% 100%;
    width: var(--字素宽度);
    height: var(--字素高度);
    background-repeat: no-repeat;
    position: absolute;
    top: var(--字素垂直位置);
    left: 50%;
    transform: translate(-50%);
    filter: drop-shadow(0 0 1px var(--字素颜色))
      brightness(var(--字素亮度)) contrast(var(--字素对比度))!important; 
    pointer-events: none;
  z-index: var(--字素层级);
}

.mes .avatar {
    position: absolute;
    top: var(--上边距);
    mix-blend-mode: var(--头像混合);
  left: var(--头像左边距);
}

.mes .avatar img {
    box-shadow: none;
    width: var(--宽度) !important;
    height: var(--高度) !important;
    border: 0 !important;
    -webkit-mask-image: 

        linear-gradient(
            to bottom, 
            black 0%, 
            black var(--底部渐变), 
            transparent 100%
        );

    mask-image: 

        linear-gradient(
            to bottom, 
            black 0%, 
            black var(--底部渐变), 
            transparent 100%
        );
    object-fit: cover;
  object-position: var(--头像位置);
}

.avatar img {
    box-shadow: none!important;
    border: 2px groove;
}

.mes::after{
  content: var(--文本);
  font-size: 10px;
  width: var(--宽度);
  height: var(--文本块高度);
  position: absolute;
  top: calc(var(--高度) + var(--上边距) + var(--文本块垂直位置));
  left: var(--头像左边距);
  overflow: hidden;
  white-space: pre-wrap;
}


.mes .name_text {
    position: absolute;
    top: calc(var(--上边距) - 20px);
    left: var(--头像左边距);
}

.mes .name_text::before {
    content: '© ';
}

.mes .name_text::after{
  content: var(--名字后文本);
  margin-left: var(--与名字间距);
}

.last_mes {
    margin-bottom: 20px!important;
}

/* 去除最后一条消息和内容之间的间距byblue老师 */
.mes.last_mes > *:not(.mes_block) {
    padding-bottom: 0;
}

/* ============================================================
   3. 消息元数据 (时间/ID/计数器)
   ============================================================ */
.mes .mes_timer, .mes .mesIDDisplay, .mes .tokenCounterDisplay {
    position: absolute;
    opacity: 0;
    font-size: 9px;
    right: 8px;
    font-weight: bold;
    font-family: "Noto Serif CJK";
    transition: opacity 0.6s ease!important;
    background: var(--SmartThemeChatTintColor);
  z-index: 1;
  box-shadow: 0 2px 3px #00000045;
}

.mesIDDisplay { top: 5px; }
.tokenCounterDisplay { top: 20px; }
.mes_timer { top: 35px; }

.timestamp {
    position: absolute;
    left: 8px;
    top: 5px;
    font-family: "Noto Serif CJK";
    opacity: 0;
    font-weight: bold;
    transition: opacity 0.6s ease!important;
}

.timestamp::before {
    content: '◎';
}

.mes:hover :is(.swipes-counter, .mes_timer, .mesIDDisplay, .tokenCounterDisplay, .timestamp) {
    opacity: 1;
    transition: opacity 0.8s ease!important;
}

/* ============================================================
   4. 界面交互与翻页组件
   ============================================================ */
.mes_edit, .extraMesButtonsHint, .extraMesButtons.visible {
    opacity: 1;
    font-size: 10px;
}

.mes_buttons, .mes_edit_buttons {
    position: absolute;
    bottom: 15px;
    left: 50%;
    transform: translateX(-50%);
    gap: 20px;
}

.mes_edit::before {
    font-family: "Noto Serif CJK";
    content: var(--编辑按钮) !important;
}

.extraMesButtonsHint::before {
    font-family: "Noto Serif CJK";
    content: var(--三点按钮) !important;
}

/* 翻页图标替换二改by 眠N勿扰老师 */
.swipe_left, .swipe_right {
    position: absolute;
    opacity: 1!important;
}

.swipe_left {
    bottom: 9px;
    margin-left: 20px;
    font-family: "Noto Serif CJK";
}

.swipe_right {
    bottom: 8px;
    font-family: "Noto Serif CJK";
}

.swipe_left::before {
    content: var(--左翻页) !important;
    font-size: 10px;
}

.swipe_right::before {
    content: var(--右翻页) !important;
    white-space: nowrap;
    margin-right: 55px;
    font-size: 10px;
}

.swipes-counter {
    font-family: "Noto Serif CJK";
    font-size: 10px;
    position: absolute;
    bottom: 9px;
    right: -1px;
    opacity: 0;
    white-space: nowrap;
    transition: opacity 0.8s ease!important;
}

/* ============================================================
   5. 导航栏与顶栏样式
   ============================================================ */
#top-bar {
    background: var(--SmartThemeChatTintColor);
    box-shadow: none;
    border: 3px double var(--SmartThemeBorderColor)!important;
    top: 1px;
}

#left-nav-panel, #right-nav-panel {
    max-height: 100vh;
}

.menu_button {
    background: transparent !important;
    color: var(--SmartThemeBodyColor);
    border: 0;
}

/* 顶栏图标by 墨千尾&秦素老师  */
#top-settings-holder .drawer-icon {
    font-size: 17px;
    opacity: 1; 
    font-family: "Noto Serif CJK";
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
}

#top-settings-holder .drawer-icon::before {
    display: inline-block;
    transition: color 0.5s ease;
    pointer-events: none;
}

#top-settings-holder > .drawer:nth-child(3n+1) .drawer-icon::before { content: var(--图标1) ; }
#top-settings-holder > .drawer:nth-child(3n+2) .drawer-icon::before { content: var(--图标3) ; }
#top-settings-holder > .drawer:nth-child(3n) .drawer-icon::before   { content: var(--图标2) ; }

#top-settings-holder .drawer-icon.closedIcon::before {
    color: var(--SmartThemeBodyColor);
}

#top-settings-holder .drawer-icon.openIcon::before {
    color: var(--SmartThemeQuoteColor) !important;
}

.drawer-content {
    box-shadow: 0 2px 3px #00000045;
}

/* ============================================================
   6. 输入框与底部功能栏
   ============================================================ */
#send_form {
    background: var(--SmartThemeChatTintColor);
    border: 3px double var(--SmartThemeBorderColor)!important;
}

.mes_text { padding: 0 10px 0 10px; }

/* 底栏图标by墨千尾老师 */
#send_form [class*="fa-"]::before {
    font-size: 17px; 
    color: var(--SmartThemeBodyColor);
    vertical-align: middle;
    font-family: "Noto Serif CJK";
}

#options_button::before { content: var(--图标1) !important; }

#extensionsMenuButton::before { content: var(--图标2) !important; }

#quick-reply-rocket-button i::before { content: var(--图标2) !important; }

#send_but::before { content: var(--图标1) !important; }

.fa-solid.fa-circle-stop::before {
    content: var(--图标4) !important; 
    color: var(--SmartThemeQuoteColor)!important;
    animation: slow-blink 2s infinite linear !important;
}

@keyframes slow-blink {
    0%, 100% { opacity: 0.3; transform: scale(0.95); }
    50% { opacity: 1; transform: scale(1); }
}

/* 输入框文字by hgu老师 */
#send_textarea::placeholder {
    color: transparent !important;
    opacity: 0 !important;
}

#nonQRFormItems { position: relative !important; }

/* 隐藏QR栏二改by 12老师 */
#qr--bar {
    max-height: 0 !important;
    opacity: 0 !important;
    pointer-events: none;
    transition: all 2s !important;
    cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

#send_form:focus-within #qr--bar {
    max-height: 120px !important;
    opacity: 1 !important;
    pointer-events: auto;
}

/* 输入时隐藏除发送键外的按钮二改by N老师 */
#send_form:has(#send_textarea:focus) {
    #leftSendForm, #quickPersonaImg, #quick-reply-rocket-button {
        display: none !important;
    }
}

/* ============================================================
   7. 通用 UI 组件 (复选框/滑动条/下拉框)
   ============================================================ */
/* 复选框二改by食南瓜者老师 */
input[type="checkbox"] {
    appearance: none;
    -webkit-appearance: none;
    width: 11px;
    height: 11px;
    border: 1px solid #666;
    background: transparent;
    border: 3px double var(--SmartThemeEmColor);
    margin-top: 4px;
}
input[type="checkbox"]:checked { background: var(--SmartThemeEmColor); border: 1px groove; }
input[type="checkbox"]::after, input[type="checkbox"]::before { content: none !important; }

/* 滑动条by 墨千尾老师 */
input[type=range] {
    border: none !important;
    box-shadow: none !important;
    height: 2px!important;
}

input[type="range"]::-webkit-slider-runnable-track {
    height: 3px;
    background: var(--SmartThemeEmColor);
    border: 0;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;    
    margin-top: -3px;
    height: 10px; 
    width: 10px;
    background-color: var(--SmartThemeBorderColor); 
    box-shadow: none;
    border: 2px groove;
}

:is(.text_pole, select, input:not([type="checkbox"]), [id*="textarea"], [class*="textarea"]) {
    background: transparent!important; 
    border: 2px groove!important; 
    padding: 0!important; 
    font-family: "Noto Serif CJK"!important; 
}

select option {
    background: var(--SmartThemeChatTintColor)!important;
    color: var(--SmartThemeBodyColor)!important;
}

[class*="select2-selection"] {
    background: transparent!important; 
    font-family: "Noto Serif CJK"!important;
}

.avatar-container.interactable.selected {
    border: 3px ridge!important; 
    background: #ffffff40;
}

/* ============================================================
   8. 文本渲染 (引用/代码/思维链)
   =========================================================== */
.mes_text q {
    quotes: none;
    display: inline-block;
    background: linear-gradient(
        to right,
        transparent 0%,
        color-mix(in srgb, var(--SmartThemeQuoteColor), transparent 95%) 20%,
        color-mix(in srgb, var(--SmartThemeQuoteColor), transparent 95%) 80%,
        transparent 100%
    );
    box-shadow: inset 0 0 10px color-mix(in srgb, var(--SmartThemeQuoteColor), transparent 85%);
    line-height: 1.5;
    padding: 0 3px;
}

.mes_text blockquote {
    position: relative;
    padding: 0 14px;
    color: var(--SmartThemeBodyColor);
    border-left: 2px solid var(--SmartThemeQuoteColor);
    font-style: italic;
    background: transparent;
}

.mes_text blockquote::before {
    content: '“'; 
    position: absolute;
    left: -5px;
    top: -5px;
    opacity: 0.5;
    font-size: 1.2em;
}

pre code, code, .mes_text pre {
    background: color-mix(in srgb, var(--SmartThemeBorderColor), transparent 95%)!important;
    font-family: "Noto Serif CJK"!important;
    color: var(--SmartThemeBodyColor)!important;
    border: 2px groove;
}

.mes_reasoning { border: 0; }

.mes_reasoning::before {
    content: '“';
    position: absolute;
    left: -12px;
    top: 40px;
    font-size: 1.6em;
}

.mes_reasoning_arrow { display: none; }

.mes_reasoning_header.flex-container { background: transparent; }

.mes_reasoning_details {
    position: relative !important;
    width: 95%;
    margin: auto;

}

.mes_reasoning_header_title { font-size: 0; }

.mes_reasoning_header_title::before {
    content: var(--思维链);
    font-weight: bold;
    font-size: 11px;
    color: var(--SmartThemeBodyColor);
    font-style: italic;

}

.mes_reasoning_actions.flex-container {
    position: absolute;
    top: -10px;
    right: 0;
    font-size: 10px;
}

.reasoning_edit_textarea { margin-top: 40px; }

/* ============================================================
   9. 系统通知与设置面板
   ============================================================ */
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader, .reverse_proxy_warning {
    border: 3px double var(--SmartThemeBorderColor)!important;
    background: #ffffff40;
    margin-top: 5px;
}

.reverse_proxy_warning {
    background: transparent!important;
    color: var(--SmartThemeQuoteColor)!important;
}

#completion_prompt_manager_list {
    background: transparent;
    border: 0!important;
}

#completion_prompt_manager .completion_prompt_manager_prompt { margin-top: 5px; }

/* 类名by hy老师 */
.completion_prompt_manager_prompt .fa-asterisk, 
.completion_prompt_manager_prompt .fa-square-poll-horizontal, 
.completion_prompt_manager_prompt .fa-syringe, 
.completion_prompt_manager_prompt .fa-thumb-tack, 
.fa-xs.fa-solid.fa-robot {
    color: var(--SmartThemeBorderColor)!important;
}

.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: var(--SmartThemeEmColor)!important;
}

#completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    border: 3px double var(--SmartThemeBorderColor)!important;
    background: #ffffff40;
}

.completion_prompt_manager_header {
    color: var(--SmartThemeBodyColor)!important;
    font-weight: bold;
}

dialog.popup, #select_chat_popup, .list-group, .select2-dropdown, #options, #extensionsMenu {
    box-shadow: 0 2px 3px #00000045;
}

/* 通知美化by serein老师 */
#toast-container > .toast { background-image: none !important; }
.toast::before {
    content: var(--图标3);
    position: absolute;
    left: 12px;
    top: 45%;
    transform: translateY(-50%);
    font-size: 25px;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}
.toast {
    background: var(--SmartThemeBlurTintColor) !important;
    border: 1px solid var(--SmartThemeEmColor);
    border-radius: 0 !important;
    color: var(--SmartThemeBodyColor) !important;
    box-shadow: 0 1px 2px #00000045!important;
}

/* ============================================================
   10. 加载动画与图标交互
   ============================================================ */
/* 消除加载多余弹窗色块byNuyoah老师 */
body:has(#load-spinner) .popup {
    background-color: transparent !important;
    box-shadow: none !important;
    border: none !important;
}

/* 加载图标修改by serein老师 */
#load-spinner {
    --spinner-size: 400px;
    transition: all var(--animation-duration-2x) ease-out;
    opacity: 1;
    top: calc(50% - var(--spinner-size) / 2);
    left: calc(50% - var(--spinner-size) / 2);
    position: absolute;
    width: var(--spinner-size);
    height: var(--spinner-size);
    background-image: var(--字素);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    filter: drop-shadow(0 0 1px var(--字素颜色))
      brightness(var(--字素亮度)) contrast(var(--字素对比度))!important; 
    animation: slide-fade-in 10s cubic-bezier(0.22, 1, 0.36, 1) forwards;
    opacity: 0;
}

#load-spinner::before { display: none !important; }

@keyframes slide-fade-in {
    0% {
        opacity: 0;
        transform: translateX(-50px); /* 从左侧 50px 的位置开始 */
    }
    100% {
        opacity: 1;
        transform: translateX(0); /* 回到原始中心位置 */
    }
}

.fa-circle-chevron-down::before,
.fa-circle-chevron-up::before,
.inline-drawer-icon.fa-circle-chevron-down::before,
.inline-drawer-icon.fa-circle-chevron-up::before {
    content: '➤' ;
    color: var(--SmartThemeEmColor) !important;
    font-family: "Noto Serif CJK";
    font-size: 10px;
    display: inline-block;
    transition: transform 0.3s ease-in-out !important;
    padding: 3px;
}

.fa-circle-chevron-down, .inline-drawer-icon.fa-circle-chevron-down {
    transition: transform 0.5s ease-in-out !important;
}

.fa-circle-chevron-up, .inline-drawer-icon.fa-circle-chevron-up {
    transform: rotate(90deg) !important; 
    transition: transform 0.5s ease-in-out !important;
}

/* ============================================================
   11. 滚动条与状态选中
   ============================================================ */
/* 滚动条by墨千尾老师 */
::-webkit-scrollbar {
    width: 3.5px;  
}

::-webkit-scrollbar-thumb {
    border: none !important; 
    background: var(--SmartThemeBorderColor)!important;
    border-radius: 0!important;
}

@media (max-width: 768px) {
    #chat::-webkit-scrollbar {
        display: none;
    }
}

.mes.selected {
    background-color: #FF000020!important;
}

::selection{
  background: var(--SmartThemeQuoteColor);
  color: var(--SmartThemeChatTintColor);
}
